// ─── METER → FEET (1,5 m = 5 ft, D&D-5e-Rastermaß) ──────────
const mToFt = str => !str ? str : str.replace(
  /(\d+(?:[,.]?\d+)?)\s*m\b/g,
  (_, n) => `${Math.round(parseFloat(n.replace(',','.')) / 1.5 * 5 / 5) * 5}ft`
);

