// ── Creator: Zaubertricks ─────────────────────────────────────
function StepCantrips({char, onChange}) {
  const cls      = CLASSES.find(c=>c.id===char.cls);
  const [open,   setOpen] = useState(null);
  const pool     = CLASS_CANTRIPS[char.cls]||[];
  const MAX      = CANTRIP_COUNT[char.cls]||2;
  const selected = char.startCantrips||[];

  const toggle = ct => {
    if (selected.includes(ct))       onChange({startCantrips: selected.filter(x=>x!==ct)});
    else if (selected.length < MAX)  onChange({startCantrips: [...selected, ct]});
  };

  if (!pool.length) return (
    <div style={{...S.card, textAlign:'center', color:MUTED, padding:24}}>
      {cls?.name} hat keine Zaubertricks.
    </div>
  );

  const accent = COL[cls?.id]||'#d4af37';
  const done   = selected.length === MAX;
  return (
    <div style={S.col}>
      <div style={{...S.row, justifyContent:'space-between', marginBottom:4}}>
        <div style={S.label}>{MAX} Zaubertrick{MAX>1?'s':''} wählen</div>
        <div style={{fontWeight:700, color:done?'#27ae60':'#d4af37'}}>
          {selected.length}/{MAX} gewählt
        </div>
      </div>
      <div style={{...S.card, fontSize:11, color:MUTED, marginBottom:8}}>
        Zaubertricks kosten keine Zauberslots und sind immer verfügbar. Tippe auf einen Balken für Beschreibung &amp; Auswahl.
      </div>

      {pool.map(ct=>{
        const isSel   = selected.includes(ct);
        const isOpen  = open===ct;
        const canPick = isSel || selected.length<MAX;
        const desc    = SPELL_DESC[ct];
        const cd      = SPELL_COMBAT_DATA[ct];
        const actInfo = cd ? (ACT_STYLE_MAP[cd.act ?? 'A'] ?? ACT_STYLE_MAP['A']) : null;
        return (
          <div key={ct} style={{marginBottom:6}}>
            {/* Kopfzeile */}
            <div onClick={()=>setOpen(isOpen?null:ct)}
              style={{...S.card, padding:'10px 14px', cursor:'pointer',
                border:`2px solid ${isSel?'#27ae60':isOpen?accent+'88':'transparent'}`,
                background: isSel?'#27ae6022' : isOpen?accent+'11' : CARD,
                borderRadius: isOpen?'8px 8px 0 0':'8px',
                opacity: !canPick ? 0.45 : 1, marginBottom:0}}>
              <div style={{...S.row, justifyContent:'space-between', gap:6}}>
                <span style={{fontSize:18, minWidth:22, flexShrink:0}}>{isSel?'✅':'○'}</span>
                <span style={{fontWeight:isSel?700:400, fontSize:13, flex:1, color:isSel?'#27ae60':TXT}}>
                  {ct}
                </span>
                {/* Aktions-Badge */}
                {actInfo && (
                  <span style={{fontSize:9, background:actInfo.bg, color:actInfo.col,
                    border:`1px solid ${actInfo.col}55`, borderRadius:5,
                    padding:'2px 5px', fontWeight:700, flexShrink:0, whiteSpace:'nowrap'}}>
                    {actInfo.label}
                  </span>
                )}
                {/* Schaden-Badge */}
                {cd?.dmg && cd.dmg!=='—' && (
                  <span style={{fontSize:10, color:DMG_COL[cd.type]||MUTED,
                    background:'#0d0d1f', borderRadius:5, padding:'2px 5px',
                    fontWeight:700, flexShrink:0, whiteSpace:'nowrap'}}>
                    {cd.dmg}{cd.type&&cd.type!=='—'?' '+cd.type:''}
                  </span>
                )}
                <span style={{color:MUTED, fontSize:14, flexShrink:0}}>{isOpen?'▲':'▼'}</span>
              </div>
            </div>
            {isOpen && (
              <div style={{background:'#111128', border:`2px solid ${isSel?'#27ae60':accent+'55'}`,
                borderTop:'none', borderRadius:'0 0 8px 8px', padding:'10px 14px',
                fontSize:12, color:MUTED, lineHeight:1.6}}>
                {/* Stat-Block */}
                {cd && (
                  <div style={{display:'flex', flexWrap:'wrap', gap:12, marginBottom:8,
                    paddingBottom:8, borderBottom:'1px solid #ffffff0d'}}>
                    {actInfo && (
                      <div>
                        <div style={{fontSize:8, color:'#555', textTransform:'uppercase', letterSpacing:.5, marginBottom:2}}>Aktion</div>
                        <div style={{fontSize:12, fontWeight:700, color:actInfo.col}}>{actInfo.label}</div>
                      </div>
                    )}
                    {cd.range && (
                      <div>
                        <div style={{fontSize:8, color:'#555', textTransform:'uppercase', letterSpacing:.5, marginBottom:2}}>Reichweite</div>
                        <div style={{fontSize:12, fontWeight:700, color:'#90caf9'}}>{cd.range}</div>
                      </div>
                    )}
                    {cd.dmg && cd.dmg!=='—' && (
                      <div>
                        <div style={{fontSize:8, color:'#555', textTransform:'uppercase', letterSpacing:.5, marginBottom:2}}>Schaden</div>
                        <div style={{fontSize:12, fontWeight:700, color:DMG_COL[cd.type]||MUTED}}>
                          {cd.dmg} {cd.type||''}
                        </div>
                      </div>
                    )}
                    {cd.roll && (
                      <div>
                        <div style={{fontSize:8, color:'#555', textTransform:'uppercase', letterSpacing:.5, marginBottom:2}}>Typ</div>
                        <div style={{fontSize:12, fontWeight:700, color:TXT}}>{cd.roll}</div>
                      </div>
                    )}
                    {cd.note && !/^Lv\d+:/i.test(cd.note.split('·')[0].trim()) && (
                      <div>
                        <div style={{fontSize:8, color:'#555', textTransform:'uppercase', letterSpacing:.5, marginBottom:2}}>Info</div>
                        <div style={{fontSize:11, color:MUTED}}>{cd.note.split('·').filter(s=>!/Lv\d+:/i.test(s.trim())).join(' · ').trim()}</div>
                      </div>
                    )}
                  </div>
                )}
                {/* Beschreibung */}
                <div style={{lineHeight:1.6}}>{desc||'Keine Beschreibung verfügbar.'}</div>
                <div style={{marginTop:10}}>
                  {isSel
                    ? <Btn sm col='#8b0000' onClick={()=>toggle(ct)}>✕ Abwählen</Btn>
                    : <Btn sm col='#27ae60' onClick={()=>canPick&&toggle(ct)}
                        disabled={!canPick}>+ Wählen</Btn>}
                </div>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

// ── Creator: Zauber ───────────────────────────────────────────
function StepSpells({char, onChange}) {
  const cls      = CLASSES.find(c=>c.id===char.cls);
  const [open,   setOpen] = useState(null);
  const MAX      = 2;
  const selected = char.startSpells||[];

  const toggle = sp => {
    if (selected.includes(sp))       onChange({startSpells: selected.filter(x=>x!==sp)});
    else if (selected.length < MAX)  onChange({startSpells: [...selected, sp]});
  };

  if (!cls?.spellcaster || !cls?.spells?.length) return (
    <div style={{...S.card, textAlign:'center', color:MUTED, padding:24}}>
      {cls?.name} beginnt ohne Zauber.
    </div>
  );

  const accent = COL[cls.id]||'#d4af37';
  const done   = selected.length === MAX;
  return (
    <div style={S.col}>
      <div style={{...S.row, justifyContent:'space-between', marginBottom:4}}>
        <div style={S.label}>2 Startzauber wählen</div>
        <div style={{fontWeight:700, color:done?'#27ae60':'#d4af37'}}>
          {selected.length}/{MAX} gewählt
        </div>
      </div>
      <div style={{...S.card, fontSize:11, color:MUTED, marginBottom:8}}>
        Tippe auf einen Balken für Beschreibung &amp; Auswahl.
      </div>

      {cls.spells.map(sp=>{
        const isSel   = selected.includes(sp);
        const isOpen  = open===sp;
        const canPick = isSel || selected.length<MAX;
        const desc    = SPELL_DESC[sp];
        return (
          <div key={sp} style={{marginBottom:6}}>
            {/* Ganzer Balken klickbar → Beschreibung auf/zu */}
            <div onClick={()=>setOpen(isOpen?null:sp)}
              style={{...S.card, padding:'10px 14px', cursor:'pointer',
                border:`2px solid ${isSel?'#27ae60':isOpen?accent+'88':'transparent'}`,
                background: isSel?'#27ae6022' : isOpen?accent+'11' : CARD,
                borderRadius: isOpen?'8px 8px 0 0':'8px',
                opacity: !canPick ? 0.45 : 1}}>
              <div style={{...S.row, justifyContent:'space-between', gap:6}}>
                <span style={{fontSize:18, minWidth:22, flexShrink:0}}>{isSel?'✅':'○'}</span>
                <span style={{fontWeight:isSel?700:400, fontSize:13, flex:1, color:isSel?'#27ae60':TXT}}>
                  {sp}
                </span>
                <span style={{color:MUTED, fontSize:14, flexShrink:0}}>{isOpen?'▲':'▼'}</span>
              </div>
            </div>
            {isOpen && (
              <div style={{background:'#1a1a32', borderLeft:`3px solid ${accent}`,
                border:`2px solid ${isSel?'#27ae60':accent+'55'}`, borderTop:'none',
                borderRadius:'0 0 8px 8px', padding:'10px 14px',
                fontSize:12, color:MUTED, lineHeight:1.6}}>
                {desc||'Keine Beschreibung verfügbar.'}
                <div style={{marginTop:10}}>
                  {isSel
                    ? <Btn sm col='#8b0000' onClick={()=>toggle(sp)}>✕ Abwählen</Btn>
                    : <Btn sm col='#27ae60' onClick={()=>canPick&&toggle(sp)}
                        disabled={!canPick}>+ Wählen</Btn>}
                </div>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

// ── Waffenlisten ──────────────────────────────────────────────
const SIMPLE_WEAPONS = [
  'Keule / Club','Dolch / Dagger','Großkeule / Greatclub','Handaxt / Handaxe',
  'Wurfspeer / Javelin','Leichter Hammer / Light Hammer','Streitkolben / Mace',
  'Stab / Quarterstaff','Sichel / Sickle','Speer / Spear',
  'Leichte Armbrust / Light Crossbow','Wurfpfeile / Darts',
  'Steinschleuder / Sling','Kurzbogen / Shortbow',
];
const MARTIAL_WEAPONS = [
  'Streitaxt / Battleaxe','Flegel / Flail','Glaive','Großaxt / Greataxe',
  'Großschwert / Greatsword','Hellebarde / Halberd','Lanze / Lance',
  'Langschwert / Longsword','Kriegspick / War Pick','Morgenstern / Morningstar',
  'Rapier','Kurzschwert / Shortsword','Dreizack / Trident',
  'Kriegshammer / Warhammer','Zweihänder / Maul','Peitsche / Whip',
  'Handarmbrüste / Hand Crossbows','Schwere Armbrust / Heavy Crossbow',
  'Langbogen / Longbow','Netz / Net',
];

// Gibt zurück wie viele Waffen gewählt werden müssen und aus welchem Pool
// Gibt { cls } zurück wenn Hintergrund einen Magic-Initiate-Feat hat
function needsBgMagic(char) {
  if (!char.bg) return null;
  const bg = BACKGROUNDS.find(b => b.id === char.bg);
  if (!bg) return null;
  const MAP = { magicInitCleric:'cleric', magicInitDruid:'druid', magicInitWizard:'wizard' };
  const cls = MAP[bg.featId];
  return cls ? { cls } : null;
}

function needsWeaponChoice(char) {
  if (char.race === 'robot' && char.sub === 'battle')
    return {count:4, pool:[...SIMPLE_WEAPONS,...MARTIAL_WEAPONS], label:'4 Waffen (Einfach oder Kriegswaffe)'};
  return null;
}

// ── Creator: Hintergrund-Magie (Magic Initiate) ──────────────
function StepBgMagic({char, onChange}) {
  const bgMagic = needsBgMagic(char);
  if (!bgMagic) return null;
  const { cls } = bgMagic;
  const clsObj   = CLASSES.find(c => c.id === cls);
  const clsLabel = clsObj ? `${clsObj.icon} ${clsObj.name}` : cls;
  const bg       = BACKGROUNDS.find(b => b.id === char.bg);
  const ACC      = '#9b59b6';
  const ACC2     = '#5dade2';

  const cantripPool    = CLASS_CANTRIPS[cls] || [];
  const spellPool      = WIKI_SPELLS.filter(s => s.lvl === 1 && s.cls && s.cls.includes(cls));
  const chosenCantrips = char.bgCantrips || [];
  const chosenSpells   = char.bgSpells   || [];

  const [openCt,  setOpenCt]  = useState(null);
  const [openSp,  setOpenSp]  = useState(null);

  const toggleCantrip = name => {
    if (chosenCantrips.includes(name)) onChange({bgCantrips: chosenCantrips.filter(x=>x!==name)});
    else if (chosenCantrips.length < 2) onChange({bgCantrips: [...chosenCantrips, name]});
  };
  const toggleSpell = name => {
    onChange({bgSpells: chosenSpells[0]===name ? [] : [name]});
  };

  // Hilfsfunktion: expandierbare Karte (identisch zu StepCantrips)
  const renderCantripCard = (ct) => {
    const isSel   = chosenCantrips.includes(ct);
    const isOpen  = openCt === ct;
    const canPick = isSel || chosenCantrips.length < 2;
    const desc    = SPELL_DESC[ct];
    const cd      = SPELL_COMBAT_DATA[ct];
    const actInfo = cd ? (ACT_STYLE_MAP[cd.act ?? 'A'] ?? ACT_STYLE_MAP['A']) : null;
    return (
      <div key={ct} style={{marginBottom:6}}>
        <div onClick={()=>setOpenCt(isOpen ? null : ct)}
          style={{...S.card, padding:'10px 14px', cursor:'pointer',
            border:`2px solid ${isSel?'#27ae60':isOpen?ACC+'88':'transparent'}`,
            background: isSel?'#27ae6022' : isOpen?ACC+'11' : CARD,
            borderRadius: isOpen?'8px 8px 0 0':'8px',
            opacity: !canPick ? 0.4 : 1, marginBottom:0}}>
          <div style={{...S.row, justifyContent:'space-between', gap:6}}>
            <span style={{fontSize:16, minWidth:20, flexShrink:0}}>{isSel?'✅':'○'}</span>
            <span style={{fontWeight:isSel?700:400, fontSize:13, flex:1,
              color:isSel?'#27ae60':TXT}}>{ct}</span>
            {actInfo && (
              <span style={{fontSize:9, background:actInfo.bg, color:actInfo.col,
                border:`1px solid ${actInfo.col}55`, borderRadius:5,
                padding:'2px 5px', fontWeight:700, flexShrink:0, whiteSpace:'nowrap'}}>
                {actInfo.label}
              </span>
            )}
            {cd?.dmg && cd.dmg!=='—' && (
              <span style={{fontSize:10, color:DMG_COL[cd.type]||MUTED,
                background:'#0d0d1f', borderRadius:5, padding:'2px 5px',
                fontWeight:700, flexShrink:0}}>{cd.dmg}{cd.type&&cd.type!=='—'?' '+cd.type:''}</span>
            )}
            <span style={{color:MUTED, fontSize:14, flexShrink:0}}>{isOpen?'▲':'▼'}</span>
          </div>
        </div>
        {isOpen && (
          <div style={{background:'#110f1e', border:`2px solid ${isSel?'#27ae6066':ACC+'44'}`,
            borderTop:'none', borderRadius:'0 0 8px 8px', padding:'10px 14px',
            fontSize:12, color:MUTED, lineHeight:1.6}}>
            {cd && (
              <div style={{display:'flex', flexWrap:'wrap', gap:12, marginBottom:8,
                paddingBottom:8, borderBottom:'1px solid #ffffff0d'}}>
                {actInfo && <div>
                  <div style={{fontSize:8,color:'#555',textTransform:'uppercase',letterSpacing:.5,marginBottom:2}}>Aktion</div>
                  <div style={{fontSize:12,fontWeight:700,color:actInfo.col}}>{actInfo.label}</div>
                </div>}
                {cd.range && <div>
                  <div style={{fontSize:8,color:'#555',textTransform:'uppercase',letterSpacing:.5,marginBottom:2}}>Reichweite</div>
                  <div style={{fontSize:12,fontWeight:700,color:'#90caf9'}}>{cd.range}</div>
                </div>}
                {cd.dmg && cd.dmg!=='—' && <div>
                  <div style={{fontSize:8,color:'#555',textTransform:'uppercase',letterSpacing:.5,marginBottom:2}}>Schaden</div>
                  <div style={{fontSize:12,fontWeight:700,color:DMG_COL[cd.type]||MUTED}}>{cd.dmg} {cd.type||''}</div>
                </div>}
              </div>
            )}
            <div style={{lineHeight:1.6}}>{desc||'Keine Beschreibung verfügbar.'}</div>
            <div style={{marginTop:10}}>
              {isSel
                ? <Btn sm col='#5a0000' onClick={()=>toggleCantrip(ct)}>✕ Abwählen</Btn>
                : <Btn sm col={ACC} onClick={()=>canPick&&toggleCantrip(ct)}
                    disabled={!canPick}>+ Wählen</Btn>}
            </div>
          </div>
        )}
      </div>
    );
  };

  return (
    <div style={S.col}>
      <div style={S.label}>Hintergrund-Magie</div>
      <div style={{...S.card, background:'#1a0a2e', borderLeft:`3px solid ${ACC}`, marginBottom:8, fontSize:12, lineHeight:1.6}}>
        <div style={{fontWeight:700, color:'#c39bd3', marginBottom:4}}>{bg?.feat}</div>
        <div style={{color:MUTED}}>
          Wähle <b style={{color:TXT}}>2 Zaubertricks</b> und <b style={{color:TXT}}>1 Grad-1-Zauber</b> aus der {clsLabel}-Liste.
          Du kannst den Grad-1-Zauber 1× täglich ohne Slotverbrauch wirken.
        </div>
      </div>

      {/* ── Zaubertricks (expandierbare Karten) ── */}
      <div style={{...S.row, justifyContent:'space-between', marginBottom:6}}>
        <div style={{fontSize:12, fontWeight:700, color:ACC}}>🔮 Zaubertricks</div>
        <div style={{fontSize:12, fontWeight:700,
          color: chosenCantrips.length===2 ? '#27ae60' : '#d4af37'}}>
          {chosenCantrips.length}/2
        </div>
      </div>
      <div style={{marginBottom:14}}>
        {cantripPool.map(ct => renderCantripCard(ct))}
      </div>

      {/* ── Grad-1-Zauber (expandierbar) ── */}
      <div style={{...S.row, justifyContent:'space-between', marginBottom:6}}>
        <div style={{fontSize:12, fontWeight:700, color:ACC2}}>✨ Grad-1-Zauber</div>
        <div style={{fontSize:12, fontWeight:700,
          color: chosenSpells.length===1 ? '#27ae60' : '#d4af37'}}>
          {chosenSpells.length}/1
        </div>
      </div>
      <div style={{display:'flex', flexDirection:'column', gap:5}}>
        {spellPool.map(s => {
          const sel  = chosenSpells.includes(s.name);
          const dis  = !sel && chosenSpells.length >= 1;
          const isOp = openSp === s.name;
          return (
            <div key={s.name} style={{marginBottom:4}}>
              <div onClick={()=>setOpenSp(isOp?null:s.name)}
                style={{...S.card, cursor:'pointer', padding:'10px 12px',
                  border:`2px solid ${sel?ACC2:isOp?ACC2+'55':'transparent'}`,
                  background: sel?'#071828':isOp?'#05101e':CARD,
                  borderRadius: isOp?'8px 8px 0 0':'8px',
                  opacity:dis?0.4:1, marginBottom:0}}>
                <div style={{...S.row, justifyContent:'space-between', gap:6}}>
                  <span style={{fontSize:16,minWidth:20,flexShrink:0}}>{sel?'✅':'○'}</span>
                  <span style={{fontWeight:sel?700:400,fontSize:13,flex:1,
                    color:sel?ACC2:TXT}}>{s.name}</span>
                  <span style={{fontSize:9,color:'#9b59b6',background:'#1a0a2e',
                    borderRadius:5,padding:'2px 5px',flexShrink:0}}>{s.school}</span>
                  <span style={{fontSize:9,color:MUTED,flexShrink:0,whiteSpace:'nowrap'}}>{s.cast}</span>
                  <span style={{color:MUTED,fontSize:14,flexShrink:0}}>{isOp?'▲':'▼'}</span>
                </div>
              </div>
              {isOp && (
                <div style={{background:'#050f1a', border:`2px solid ${sel?ACC2+'66':ACC2+'33'}`,
                  borderTop:'none', borderRadius:'0 0 8px 8px', padding:'10px 12px',
                  fontSize:12, color:MUTED, lineHeight:1.6}}>
                  <div style={{display:'flex', gap:12, flexWrap:'wrap', marginBottom:8,
                    paddingBottom:8, borderBottom:'1px solid #ffffff0d'}}>
                    <div>
                      <div style={{fontSize:8,color:'#555',textTransform:'uppercase',letterSpacing:.5,marginBottom:2}}>Schule</div>
                      <div style={{fontSize:12,fontWeight:700,color:'#9b59b6'}}>{s.school}</div>
                    </div>
                    <div>
                      <div style={{fontSize:8,color:'#555',textTransform:'uppercase',letterSpacing:.5,marginBottom:2}}>Wirkzeit</div>
                      <div style={{fontSize:12,fontWeight:700,color:TXT}}>{s.cast}</div>
                    </div>
                    <div>
                      <div style={{fontSize:8,color:'#555',textTransform:'uppercase',letterSpacing:.5,marginBottom:2}}>Reichweite</div>
                      <div style={{fontSize:12,fontWeight:700,color:'#90caf9'}}>{s.range}</div>
                    </div>
                    <div>
                      <div style={{fontSize:8,color:'#555',textTransform:'uppercase',letterSpacing:.5,marginBottom:2}}>Dauer</div>
                      <div style={{fontSize:12,fontWeight:700,color:TXT}}>{s.dur}</div>
                    </div>
                  </div>
                  <div style={{lineHeight:1.65}}>{s.desc}</div>
                  <div style={{marginTop:10}}>
                    {sel
                      ? <Btn sm col='#5a0000' onClick={()=>toggleSpell(s.name)}>✕ Abwählen</Btn>
                      : <Btn sm col={ACC2} onClick={()=>!dis&&toggleSpell(s.name)}
                          disabled={dis}>+ Wählen</Btn>}
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* Zusammenfassung */}
      {chosenCantrips.length===2 && chosenSpells.length===1 && (
        <div style={{marginTop:10, padding:'10px 12px', background:'#0a1f0a',
          borderRadius:8, border:'1px solid #27ae60', fontSize:12}}>
          ✅ {chosenCantrips.join(' · ')} · {chosenSpells[0]}
        </div>
      )}
    </div>
  );
}

