// Partial-Match-Lookup: Suche nach dem längsten passenden Schlüssel
function getFeatureDesc(f) {
  let best = null, bestLen = 0;
  for (const k of Object.keys(FEATURE_DESC)) {
    if (f.startsWith(k) || f.includes(k)) {
      if (k.length > bestLen) { best = k; bestLen = k.length; }
    }
  }
  return best ? FEATURE_DESC[best] : null;
}

// Self-contained card for one multiclass entry (has its own openF / showFut state)
function McFeaturesCard({mc, sheet}) {
  const mcCls    = CLASSES.find(c => c.id === mc.id);
  const mcAccent = COL[mc.id] || '#3498db';
  const [openF,   setOpenF]   = useState(null);
  const [showFut, setShowFut] = useState(false);
  if (!mcCls) return null;

  const chosenSubData = mc.sub ? SUBCLASS_FEATURES?.[mc.sub] : null;
  const unlockedLevels = [], futureLevels = [];
  for (let l = 1; l <= 20; l++) {
    const ff = mcCls.features?.[l];
    if (!ff) continue;
    if (l <= mc.lv) unlockedLevels.push({l, ff});
    else             futureLevels.push({l, ff});
  }

  const renderFeatureRow = (f, fi, l, unlocked) => {
    const isSubRow = f.toLowerCase().includes('subclass') || f.toLowerCase().includes('subklasse');
    if (isSubRow) {
      const subFeats = chosenSubData?.[l];
      return (
        <div key={fi} style={{marginBottom:4}}>
          <div style={{background:unlocked?mcAccent+'22':'#14142a', borderRadius:8,
            padding:'7px 10px', marginBottom:4,
            border:`1px solid ${unlocked?mcAccent+'55':'transparent'}`}}>
            <div style={{fontSize:13, fontWeight:700, color:unlocked?mcAccent:'#555'}}>
              ⚡ {mc.sub ? (mc.subName||mc.sub) : 'Subklasse — wird bei Level-Up gewählt'}
            </div>
          </div>
          {subFeats && subFeats.map((sf, sfi) => {
            const sfKey = `mcsub-${mc.id}-${l}-${sfi}`;
            const sfOpen = openF === sfKey;
            return (
              <div key={sfi} onClick={()=>setOpenF(sfOpen?null:sfKey)}
                style={{background:unlocked?(sfOpen?mcAccent+'18':'#1a1a2e'):'#14142a',
                  borderRadius:8, padding:'8px 12px', marginBottom:3, cursor:'pointer',
                  border:`1px solid ${sfOpen?mcAccent+'77':mcAccent+'33'}`, marginLeft:8}}>
                <div style={{...S.row, justifyContent:'space-between', gap:6}}>
                  <span style={{fontSize:13, fontWeight:600, color:unlocked?TXT:'#555', flex:1}}>{sf.name}</span>
                  <span style={{color:MUTED, fontSize:12}}>{sfOpen?'▲':'▼'}</span>
                </div>
                {sfOpen && <div style={{marginTop:7, borderTop:'1px solid #333', paddingTop:7}}><DescText text={sf.desc}/></div>}
              </div>
            );
          })}
          {!subFeats && mc.sub && (
            <div style={{marginLeft:8, fontSize:12, color:MUTED, fontStyle:'italic'}}>
              Weitere Details werden auf diesem Level freigeschaltet.
            </div>
          )}
        </div>
      );
    }
    const desc  = getFeatureDesc(f);
    const key   = `mc-${mc.id}-${l}-${fi}`;
    const isOpen = openF === key;
    return (
      <div key={fi} onClick={() => desc && setOpenF(isOpen ? null : key)}
        style={{background:unlocked?(isOpen?mcAccent+'18':'#1e1e3a'):'#14142a',
          borderRadius:8, padding:'7px 10px', marginBottom:3,
          border:`1px solid ${isOpen?mcAccent+'55':'transparent'}`,
          cursor:desc?'pointer':'default'}}>
        <div style={{...S.row, justifyContent:'space-between', gap:6}}>
          <span style={{fontSize:13, fontWeight:600, color:unlocked?TXT:'#555', flex:1}}>{f}</span>
          {desc && <span style={{color:MUTED, fontSize:12, flexShrink:0}}>{isOpen?'▲':'▼'}</span>}
        </div>
        {isOpen && desc && (
          <div style={{marginTop:7, borderTop:'1px solid #333', paddingTop:7}}><DescText text={desc}/></div>
        )}
      </div>
    );
  };

  const renderLevel = (l, ff, unlocked) => (
    <div key={l} style={{marginBottom:6}}>
      <div style={{fontSize:10, fontWeight:700, letterSpacing:1.2, textTransform:'uppercase',
        color:unlocked?mcAccent:'#555', marginBottom:3}}>
        {unlocked ? '▸' : '○'} Stufe {l}
      </div>
      {ff.map((f, fi) => renderFeatureRow(f, fi, l, unlocked))}
    </div>
  );

  return (
    <div style={S.card}>
      <div style={{...S.row, justifyContent:'space-between', marginBottom:10, alignItems:'center'}}>
        <div style={{...S.label, color:mcAccent}}>
          {mcCls.icon} Multiclass: {mcCls.name}
        </div>
        <span style={{fontSize:11, background:mcAccent+'22', color:mcAccent,
          padding:'2px 10px', borderRadius:8, fontWeight:700}}>Stufe {mc.lv}</span>
      </div>
      {unlockedLevels.map(({l, ff}) => renderLevel(l, ff, true))}
      {futureLevels.length > 0 && (
        <>
          <div onClick={()=>setShowFut(v=>!v)}
            style={{...S.row, justifyContent:'space-between', cursor:'pointer',
              padding:'8px 10px', marginTop:4, borderRadius:8,
              background:'#181828', border:`1px solid #333`}}>
            <span style={{fontSize:12, color:MUTED}}>
              {showFut?'▲':'▼'} Zukünftige Level ({futureLevels.length} Stufen, Lv{futureLevels[0].l}–20)
            </span>
          </div>
          {showFut && (
            <div style={{marginTop:6, opacity:0.55}}>
              {futureLevels.map(({l, ff}) => renderLevel(l, ff, false))}
            </div>
          )}
        </>
      )}
    </div>
  );
}

function FeaturesTab({sheet, accent, onUpdate}) {
  const cls  = CLASSES.find(c=>c.id===sheet.cls);
  const race = RACES.find(r=>r.id===sheet.race);
  const sub  = race?.subraces?.find(s=>s.id===sheet.sub);
  const bg   = BACKGROUNDS.find(b=>b.id===sheet.bg);
  const lv        = sheet.lv||1;
  const mcTotalLv = (sheet.multiclasses||[]).reduce((s,m)=>s+m.lv,0);
  const primaryLv = lv - mcTotalLv;

  // Feature expand state
  const [openF,      setOpenF]      = useState(null);
  const [showFuture, setShowFuture] = useState(false);
  // Section collapse (all closed by default)
  const [clsOpen,  setClsOpen]  = useState(false);
  const [raceOpen, setRaceOpen] = useState(false);
  const [bgOpen,   setBgOpen]   = useState(false);
  // Race trait expand
  const [openTrait, setOpenTrait] = useState(null);
  // BG item expand (single key)
  const [openBgItem, setOpenBgItem] = useState(null);

  // Notizen & Hilfe (collapsed by default)
  const [notesOpen,       setNotesOpen]       = useState(false);
  const [helpOpen,        setHelpOpen]         = useState(false);
  const [helpSectionOpen, setHelpSectionOpen]  = useState(null);
  const [newLabel,        setNewLabel]         = useState('');

  const appFields = [
    {key:'aussehen_alter',   label:'Alter'},
    {key:'aussehen_groesse', label:'Größe'},
    {key:'aussehen_gewicht', label:'Gewicht'},
    {key:'aussehen_augen',   label:'Augen'},
    {key:'aussehen_haare',   label:'Haare'},
    {key:'aussehen_haut',    label:'Haut'},
  ];
  const textFields = [
    ['notizenCharakter',  'Charakterbeschreibung'],
    ['notizenPersonality','Persönlichkeitszüge'],
    ['notizenIdeale',     'Ideale'],
    ['notizenBonds',      'Bindungen'],
    ['notizenFlaws',      'Makel'],
    ['notizenBackstory',  'Hintergrundgeschichte'],
    ['notizenAllies',     'Verbündete & Organisationen'],
    ['notizenSonstiges',  'Sonstiges'],
  ];
  const customNotes = sheet.customNotes || [];
  const addSection = () => {
    const label = newLabel.trim();
    if (!label) return;
    const section = {id: Date.now().toString(), label, content: ''};
    onUpdate({customNotes: [...customNotes, section]});
    setNewLabel('');
  };
  const updateSection = (id, field, value) =>
    onUpdate({customNotes: customNotes.map(s => s.id===id ? {...s,[field]:value} : s)});
  const deleteSection = (id) =>
    onUpdate({customNotes: customNotes.filter(s => s.id!==id)});

  const bgFeatData  = bg?.featId ? WIKI_FEATS.find(f=>f.id===bg.featId) : null;
  const chosenSubId   = sheet.chosenSubclass;
  const chosenSubData = chosenSubId ? SUBCLASS_FEATURES?.[chosenSubId] : null;

  // Level in freigeschaltet / zukünftig aufteilen
  const unlockedLevels = [];
  const futureLevels   = [];
  for (let l=1; l<=20; l++) {
    const ff = cls?.features?.[l];
    if (!ff) continue;
    if (l <= lv) unlockedLevels.push({l, ff});
    else         futureLevels.push({l, ff});
  }

  // ── Sektion-Header (klappbar) ──────────────────────────────
  const SectionHeader = ({label, open, onToggle, color}) => (
    <div onClick={onToggle}
      style={{...S.row, justifyContent:'space-between', cursor:'pointer',
        marginBottom: open ? 10 : 0}}>
      <div style={{...S.label, color: color||TXT}}>{label}</div>
      <span style={{color:MUTED, fontSize:14, flexShrink:0}}>{open?'▲':'▼'}</span>
    </div>
  );

  // ── Klassen-Feature-Zeile ──────────────────────────────────
  const renderFeatureRow = (f, fi, l, unlocked) => {
    const isSubRow = f.toLowerCase().includes('subclass') || f.toLowerCase().includes('subklasse');

    if (isSubRow) {
      const subFeats = chosenSubData?.[l];
      return (
        <div key={fi} style={{marginBottom:4}}>
          <div style={{background: unlocked ? accent+'22' : '#14142a',
            borderRadius:8, padding:'7px 10px', marginBottom:4,
            border:`1px solid ${unlocked ? accent+'55' : 'transparent'}`}}>
            <div style={{fontSize:13, fontWeight:700, color: unlocked ? accent : '#555'}}>
              ⚡ {chosenSubId ? (sheet.chosenSubclassName || chosenSubId) : 'Subklasse — wird bei Level-Up gewählt'}
            </div>
          </div>
          {subFeats && subFeats.map((sf, sfi) => {
            const sfKey  = `sub-${l}-${sfi}`;
            const sfOpen = openF === sfKey;
            return (
              <div key={sfi} onClick={()=>setOpenF(sfOpen?null:sfKey)}
                style={{background: unlocked ? (sfOpen ? accent+'18' : '#1a1a2e') : '#14142a',
                  borderRadius:8, padding:'8px 12px', marginBottom:3, cursor:'pointer',
                  border:`1px solid ${sfOpen ? accent+'77' : accent+'33'}`, marginLeft:8}}>
                <div style={{...S.row, justifyContent:'space-between', gap:6}}>
                  <span style={{fontSize:13, fontWeight:600, color: unlocked?TXT:'#555', flex:1}}>{sf.name}</span>
                  <span style={{color:MUTED, fontSize:12}}>{sfOpen?'▲':'▼'}</span>
                </div>
                {sfOpen && <div style={{marginTop:7, borderTop:'1px solid #333', paddingTop:7}}><DescText text={sf.desc}/></div>}
              </div>
            );
          })}
          {!subFeats && chosenSubId && (
            <div style={{marginLeft:8, fontSize:12, color:MUTED, fontStyle:'italic'}}>
              Weitere Details werden auf diesem Level freigeschaltet.
            </div>
          )}
        </div>
      );
    }

    const desc   = getFeatureDesc(f);
    const key    = `${l}-${fi}`;
    const isOpen = openF === key;
    return (
      <div key={fi} onClick={() => desc && setOpenF(isOpen ? null : key)}
        style={{background: unlocked ? (isOpen ? accent+'18' : '#1e1e3a') : '#14142a',
          borderRadius:8, padding:'7px 10px', marginBottom:3,
          border:`1px solid ${isOpen ? accent+'55' : 'transparent'}`,
          cursor: desc ? 'pointer' : 'default'}}>
        <div style={{...S.row, justifyContent:'space-between', gap:6}}>
          <span style={{fontSize:13, fontWeight:600, color: unlocked ? TXT : '#555', flex:1}}>{f}</span>
          {desc && <span style={{color:MUTED, fontSize:12, flexShrink:0}}>{isOpen?'▲':'▼'}</span>}
        </div>
        {isOpen && desc && <div style={{marginTop:7, borderTop:'1px solid #333', paddingTop:7}}><DescText text={desc}/></div>}
      </div>
    );
  };

  const renderLevel = (l, ff, unlocked) => (
    <div key={l} style={{marginBottom:6}}>
      <div style={{fontSize:10, fontWeight:700, letterSpacing:1.2, textTransform:'uppercase',
        color: unlocked ? accent : '#555', marginBottom:3}}>
        {unlocked ? '▸' : '○'} Stufe {l}
      </div>
      {ff.map((f, fi) => renderFeatureRow(f, fi, l, unlocked))}
    </div>
  );

  // ── Hintergrund-Einzel-Item (aufklappbar) ─────────────────
  const bgItem = (key, icon, label, labelColor, summary, detail) => {
    const isOpen = openBgItem === key;
    return (
      <div onClick={()=>setOpenBgItem(isOpen ? null : key)}
        style={{background: isOpen ? '#1a1a30' : '#181828', borderRadius:8,
          padding:'8px 11px', marginBottom:5, cursor:'pointer',
          border:`1px solid ${isOpen ? '#ffffff22' : 'transparent'}`}}>
        <div style={{...S.row, justifyContent:'space-between', alignItems:'center'}}>
          <div style={{flex:1, minWidth:0}}>
            <div style={{fontSize:9, color:labelColor||MUTED, fontWeight:700, letterSpacing:0.8,
              textTransform:'uppercase', marginBottom:2}}>{icon} {label}</div>
            {!isOpen && <div style={{fontSize:12, color:TXT, lineHeight:1.4}}>{summary}</div>}
          </div>
          <span style={{color:MUTED, fontSize:12, flexShrink:0, marginLeft:6}}>{isOpen?'▲':'▼'}</span>
        </div>
        {isOpen && (
          <div style={{marginTop:8, paddingTop:8, borderTop:'1px solid #ffffff11',
            fontSize:12, color:MUTED, lineHeight:1.65}}>
            {detail}
          </div>
        )}
      </div>
    );
  };

  // ── Rassen-Merkmal (aufklappbar) ──────────────────────────
  const allTraits = [...(race?.traits||[]), ...(sub?.traits||[])];

  const helpSections = [
    {id:'dist',title:'Entfernungen / Distances (ft ↔ m)',content:'Umrechnung / Conversion:\n5 ft = 1,5 m · 10 ft = 3 m · 15 ft = 4,5 m · 20 ft = 6 m\n30 ft = 9 m · 60 ft = 18 m · 90 ft = 27 m · 120 ft = 36 m'},
    {id:'combat',title:'Kampf-Begriffe / Combat Terms',content:'Angriffsaktion / Attack Action:\nWürfle W20 + Angriffs-Mod ≥ Rüstungsklasse (AC) des Ziels → Treffer.\nBei Treffer: Schadenswürfel + Modifikator würfeln.\n\nKritischer Treffer / Critical Hit:\n20 auf W20 (natürliche 20) → alle Schadenswürfel werden verdoppelt.\n\nVorteil / Advantage:\n2W20 würfeln und den höheren Wert nehmen.\n\nNachteil / Disadvantage:\n2W20 würfeln und den niedrigeren Wert nehmen.\n\nReaktion / Reaction:\nEinmal pro Runde — auch außer der Reihe (z.B. Gelegenheitsangriff).'},
    {id:'conditions',title:'Zustände / Conditions',content:'Vergiftet / Poisoned:\nNachteil auf Angriffswürfe & Fähigkeitsüberprüfungen.\nAufhebung / End Condition:\nEigene Rettungswürfe bestehen oder Zauberdauer endet. Lesser Restoration entfernt es sofort.\n\nBetäubt / Stunned:\nKann nicht handeln oder bewegen. Angriffe haben Vorteil gegen das Ziel. STÄ/GES-RW automatisch nicht bestanden.\nAufhebung / End Condition:\nEndet automatisch am Ende der nächsten eigenen Runde des Betroffenen.\n\nBewusstlos / Unconscious:\nFällt hin (Liegend). Nachteil auf RW. Treffer im 1,5 m = automatisch kritisch.\nAufhebung / End Condition:\nBeliebige Heilung (min. 1 HP) beendet den Zustand. Stabilisiert: Erwacht nach 1–4 Stunden mit 1 HP.\n\nBezaubert / Charmed:\nKann den Bezauberer nicht angreifen oder als Ziel eines feindlichen Effekts wählen.\nAufhebung / End Condition:\nZauberdauer endet oder Bezauberer schadet dem Bezauberten. Lesser Restoration entfernt es.\n\nErschreckt / Frightened:\nNachteil auf Angriffe & Fähigkeitswürfe solange Quelle sichtbar. Kann sich nicht nähern.\nAufhebung / End Condition:\nQuelle aus der Sichtlinie bringen. Oder Rettungswurf am Rundenende bestehen (je nach Effekt).\n\nParalysiert / Paralyzed:\nWie Bewusstlos + automatisch kritisch im 1,5 m. Keine Aktionen oder Reaktionen.\nAufhebung / End Condition:\nWEI-Rettungswurf am Ende jeder eigenen Runde (SC des Verursachers). Lesser Restoration hebt es auf.\n\nVersteint / Petrified:\nResistenz vs. alle Schadensarten. Immunität gegen Gift & Krankheit. Nachteil auf GES-RW. Zeit scheint zu stehen.\nAufhebung / End Condition:\nNur Greater Restoration, Wish oder gleichwertige Magie. Kein gewöhnlicher Rettungswurf möglich.\n\nLiegend / Prone:\nAngriffe aus 1,5 m haben Vorteil gegen das Ziel. Fernkampf-Angriffe haben Nachteil.\nAufhebung / End Condition:\nAufstehen als Teil der Bewegung — kostet halbe Bewegungsweite (z.B. 4,5 m bei 9 m Bewegung).\n\nGegriffen / Grappled:\nBewegungsweite 0. Greifer kann das Ziel mitziehen (halbe eigene Bewegung).\nAufhebung / End Condition:\nAktion: STÄ(Athletik) oder GES(Akrobatik) vs. STÄ(Athletik) des Greifenden. Oder Teleportation.'},
    {id:'rests',title:'Rasten / Rests',content:'Kurze Rast / Short Rest (1 Stunde):\nTrefferwürfel nach Belieben ausgeben (W + KON-Mod HP je Würfel).\nKi-Punkte, Zweite Luft (Fighter) und ähnliche Fähigkeiten werden erneuert.\n\nLange Rast / Long Rest (8 Stunden):\nAlle TP zurück. Hälfte der Trefferwürfel zurück (mind. 1).\nAlle Zauberslots zurück. Alle langen-Rast-Fähigkeiten zurück.'},
    {id:'attrs',title:'Attribut-Modifikatoren / Ability Modifiers',content:'Tabelle (Attributwert → Modifikator):\n1 = −5 · 2–3 = −4 · 4–5 = −3 · 6–7 = −2 · 8–9 = −1\n10–11 = +0 · 12–13 = +1 · 14–15 = +2 · 16–17 = +3\n18–19 = +4 · 20 = +5 · 22 = +6 · 24 = +7 · 25 = +7\n\nFormel / Formula:\nModifikator = ⌊(Attributwert − 10) ÷ 2⌋'},
    {id:'carry',title:'Traglast / Carrying Capacity',content:'Formel / Formula:\nMax. Traglast = STÄ-Wert × 15 Pfund (lb)\n\nBeispiele / Examples:\nSTÄ 8  → 120 lb (≈ 54 kg)\nSTÄ 10 → 150 lb (≈ 68 kg)\nSTÄ 15 → 225 lb (≈ 102 kg)\nSTÄ 20 → 300 lb (≈ 136 kg)\n\nContainer-Bonus (Hausregel):\n• Rucksack / Backpack: +50 lb\n• Tasche / Pouch/Sack: +15 lb\n• Truhe / Chest/Kiste: +100 lb\n• Beutel / Bag: +20 lb\n\nBelastung / Encumbrance:\nÜber max. Traglast → Bewegungsweite −3 m (optionale Regel) oder Nachteil auf STÄ/GES/KON-Würfe.\n\nHinweis:\nIm Inventar-Tab siehst du oben rechts deine aktuelle Traglast. Wenn du einen Rucksack o.ä. im Inventar hast, erhöht sich der Maximalwert automatisch.'},
    {id:'wechselkurs',title:'💰 Währung & Wechselkurs',content:'1 PM  = 10 GM = 100 SM = 200 EM = 1.000 KM\n1 GM  = 10 SM = 20 EM = 100 KM\n1 EM  = 5 SM = 50 KM\n1 SM  = 10 KM\n\nKM = Kupfermünzen (CP)\nSM = Silbermünzen (SP)\nEM = Elektrummünzen (EP)\nGM = Goldmünzen (GP) — Basiswährung\nPM = Platinmünzen (PP)'},
    {id:'actions',title:'Aktionen im Kampf / Actions in Combat',content:'Aktion / Action:\n• Angreifen / Attack: W20 + Angriffs-Mod vs. AC\n• Zaubern / Cast a Spell: Zauber-Slot verbrauchen\n• Greifen / Grapple: STÄ(Athletik) vs. STÄ(Athletik) oder GES(Akrobatik)\n• Anstupsen / Shove: STÄ(Athletik) vs. Athletik/Akrobatik → liegend oder 1,5 m weg\n• Sprint / Dash: Bewegungsweite für diese Runde verdoppeln\n• Rückzug / Disengage: Bewegung löst keine Gelegenheitsangriffe aus\n• Ausweichen / Dodge: Angriffe gegen dich mit Nachteil bis nächste Runde\n• Helfen / Help: Verbündeter hat Vorteil auf nächsten Angriff oder Fähigkeitswurf\n• Verstecken / Hide: GES(Heimlichkeit / Stealth)-Wurf\n• Bereit / Ready: Aktion festlegen + Auslösebedingung → als Reaktion ausführen\n• Zwei-Waffen-Kampf / Two-Weapon Fighting: Bonusaktion mit leichter Waffe\n\nBonus-Aktion / Bonus Action:\n• Zweite leichte Waffe (ohne Mod zum Schaden, außer Two-Weapon Fighting)\n• Klassenfeature (Raserei / Rage, Cunning Action / Schlaue Aktion, usw.)\n• Bestimmte Zauber (Befehl / Command, Heilender Segen / Healing Word …)\n\nReaktion / Reaction:\n• Gelegenheitsangriff / Opportunity Attack: Feind verlässt Reichweite → 1 Angriff\n• Bereit-Aktion / Readied Action auslösen\n• Klassen-Reaktionen (Uncanny Dodge / Ungl. Ausweichung, Parry …)'},
  ];
  const kampfRegelwerk = (
    <>
      {[
        {col:'#7986cb',lbl:'ANGRIFFSWURF',lines:['W20 + Attribut-Mod + Übungsbonus (wenn geübt) ≥ AC des Ziels → Treffer','Natürliche 20 = Krit · Natürliche 1 = automatisch verfehlt','Fernkampfangriff mit Feind in 1,5 m Nähe: Nachteil auf Angriffswurf']},
        {col:'#e74c3c',lbl:'KRITISCHER TREFFER',lines:['Natürliche 20: Alle Schadenswürfel EINMAL EXTRA würfeln und addieren','Modifikatoren werden normal addiert (kein Extra-Mod). Champion: 19–20 = Krit']},
        {col:'#e67e22',lbl:'SCHADEN & SCHADENTYPEN',lines:['Resistenz = halber Schaden · Immunität = kein Schaden · Anfälligkeit = doppelt','Typen: Säure · Kälte · Feuer · Kraft · Blitz · Nekrose · Gift · Psychisch · Strahlung · Donner · Wucht · Stich · Hieb']},
        {col:'#27ae60',lbl:'DECKUNG / COVER',lines:['• Halbe Deckung: +2 auf AC und GES-Rettungswürfe','• Dreiviertel-Deckung: +5 auf AC und GES-Rettungswürfe','• Vollständige Deckung: Nicht direkt angreifbar (AoE-Zauber oft ignorieren Deckung)']},
        {col:'#9b59b6',lbl:'GELEGENHEITSANGRIFF',lines:['Kreatur verlässt Nahkampfbereich (1,5 m) → Reaktionsangriff','Sprint, Teleport und Rückzug (Disengage) verhindern Gelegenheitsangriffe']},
        {col:'#2980b9',lbl:'KONZENTRATION',lines:['Nur 1 Konzentrationseffekt aktiv. Neuer Zauber beendet den vorherigen','Bei Schaden: KON-RW DC 10 oder halber Schaden (höherer gilt)','War Caster: Vorteil auf KON-RW · Betäubt/Kampfunfähig: sofortiger Verlust']},
        {col:'#c0392b',lbl:'STERBEN & STABILISIEREN',lines:['0 TP: Bewusstlos. Pro Runde W20 — ≥10 = Erfolg, ≤9 = Fehlschlag','3 Erfolge = stabil · 3 Fehlschläge = tot','Nat. 1 = 2 Fehlschläge · Nat. 20 = 1 TP sofort zurück','Nahkampf-Krit bei 0 TP = 2 Fehlschläge · Stabil: 1W4 Std. ohnmächtig, dann 1 TP']},
        {col:'#16a085',lbl:'RAST / RESTS',lines:['Kurze Rast (≥1 Std): Trefferwürfel ausgeben → W + KON-Mod TP je Würfel','Lange Rast (≥8 Std, max 1×/Tag): Alle TP, halbe Trefferwürfel, alle Slots zurück']},
        {col:'#8e44ad',lbl:'ZAUBERN / SPELLCASTING',lines:['Komponenten: V = Verbal · S = Somatisch · M = Material','Zauberbeutel reicht für Materialien ohne Goldwert. Teure Komp. extra nötig','Reaktionszauber: jederzeit auslösbar, auch im Zug eines Gegners']},
        {col:'#d4af37',lbl:'BEWEGUNG & GELÄNDE',lines:['Schwieriges Gelände: jeder Meter kostet 2 m Bewegung','Klettern/Schwimmen (ohne Geschwindigkeit): 2× Bewegungskosten','Kriechen: halbe Bewegung · Aufstehen aus Liegend: halbe Bewegung ausgeben']},
        {col:'#27ae60',lbl:'INITIATIVE',lines:['W20 + GES-Modifikator zu Kampfbeginn. Alle würfeln gleichzeitig','Gleiche Initiative: STÄ-Prüfung oder DM entscheidet','Alert-Talent: +5 auf Initiative · manche Klassen haben Vorteil']},
      ].map((sec,i)=>(
        <div key={i}>
          {i>0 && <div style={S.sep}/>}
          <div style={{fontSize:10,color:sec.col,fontWeight:700,marginBottom:3,letterSpacing:0.5}}>{sec.lbl}</div>
          {sec.lines.map((l,j)=>(
            <div key={j} style={{fontSize:12,color:MUTED,marginBottom:j<sec.lines.length-1?2:0}}>{l}</div>
          ))}
        </div>
      ))}
    </>
  );

  return (
    <div style={{padding:'12px 16px'}}>

      {/* ── KLASSEN-FÄHIGKEITEN ── */}
      <div style={{...S.card, marginBottom:8}}>
        <SectionHeader
          label={`Klassen-Fähigkeiten — ${cls?.name||'—'} · Stufe ${primaryLv}`}
          open={clsOpen} onToggle={()=>setClsOpen(v=>!v)}/>
        {clsOpen && (
          <>
            {unlockedLevels.map(({l, ff}) => renderLevel(l, ff, true))}
            {futureLevels.length > 0 && (
              <>
                <div onClick={()=>setShowFuture(v=>!v)}
                  style={{...S.row, justifyContent:'space-between', cursor:'pointer',
                    padding:'8px 10px', marginTop:4, borderRadius:8,
                    background:'#181828', border:`1px solid #333`}}>
                  <span style={{fontSize:12, color:MUTED}}>
                    {showFuture ? '▲' : '▼'} Zukünftige Level ({futureLevels.length} Stufen, Lv{futureLevels[0].l}–20)
                  </span>
                </div>
                {showFuture && (
                  <div style={{marginTop:6, opacity:0.55}}>
                    {futureLevels.map(({l, ff}) => renderLevel(l, ff, false))}
                  </div>
                )}
              </>
            )}
          </>
        )}
      </div>

      {/* Multiclass-Fähigkeiten */}
      {(sheet.multiclasses||[]).map(mc => (
        <McFeaturesCard key={mc.id} mc={mc} sheet={sheet}/>
      ))}

      {/* ── RASSEN-MERKMALE ── */}
      <div style={{...S.card, marginBottom:8}}>
        <SectionHeader
          label={`Rassen-Merkmale (${race?.name||'—'}${sub ? ' · '+sub.name : ''})`}
          open={raceOpen} onToggle={()=>setRaceOpen(v=>!v)}/>
        {raceOpen && (
          <div>
            {allTraits.map((t, i) => {
              const colonIdx = t.indexOf(': ');
              const hasColon = colonIdx > 0;
              const title    = hasColon ? t.slice(0, colonIdx).trim() : t;
              const detail   = hasColon ? t.slice(colonIdx + 2).trim() : t;
              const tKey     = `trait-${i}`;
              const isOpen   = openTrait === tKey;
              return (
                <div key={i} onClick={()=>setOpenTrait(isOpen ? null : tKey)}
                  style={{background: isOpen ? accent+'18' : '#1e1e3a',
                    borderRadius:8, padding:'7px 10px', marginBottom:4, cursor:'pointer',
                    border:`1px solid ${isOpen ? accent+'55' : 'transparent'}`}}>
                  <div style={{...S.row, justifyContent:'space-between', gap:6}}>
                    <span style={{fontSize:12, fontWeight:600, color:TXT, flex:1, lineHeight:1.4}}>
                      {title}
                    </span>
                    <span style={{color:MUTED, fontSize:12, flexShrink:0}}>{isOpen?'▲':'▼'}</span>
                  </div>
                  {isOpen && (
                    <div style={{marginTop:6, borderTop:'1px solid #333', paddingTop:6,
                      fontSize:12, color:MUTED, lineHeight:1.65}}>
                      {detail}
                    </div>
                  )}
                </div>
              );
            })}
            {allTraits.length === 0 && (
              <div style={{fontSize:12, color:MUTED, fontStyle:'italic'}}>Keine Rassen-Merkmale bekannt.</div>
            )}
          </div>
        )}
      </div>

      {/* ── HINTERGRUND ── */}
      {bg && (
        <div style={{...S.card, marginBottom:8}}>
          <SectionHeader
            label={`${bg.icon} ${bg.name} (PHB 2024)`}
            open={bgOpen} onToggle={()=>setBgOpen(v=>!v)}/>
          {bgOpen && (
            <>
              {/* Attribut-Boni */}
              <div style={{display:'flex', gap:5, flexWrap:'wrap', marginBottom:8}}>
                {bg.attrBonus.map(([a,v],i)=>(
                  <span key={i} style={{fontSize:11,background:'#27ae6022',color:'#27ae60',
                    padding:'3px 8px',borderRadius:8,fontWeight:700}}>+{v} {a}</span>
                ))}
              </div>

              {/* Hintergrund-Feat */}
              {bgFeatData && bgItem('feat','⭐','Hintergrund-Feat','#9b59b6',
                bgFeatData.name, bgFeatData.desc)}

              {/* ASI-Feats (aus Level Up) */}
              {(sheet.feats||[]).map((f,i)=>(
                bgItem(`feat_${i}`,'⭐',`Feat (Lv ${f.fromLevel})`, '#d4af37', f.name, f.desc)
              ))}

              {/* Werkzeug */}
              {bg.tool && bgItem('tool','🔧','Werkzeug-Übung',MUTED,
                bg.tool, bg.tool)}

              {/* Fertigkeiten */}
              {bgItem('skills','📚','Fertigkeiten',MUTED,
                bg.skills.join(', '),
                <div>{bg.skills.map((sk,i)=>(
                  <div key={i} style={{marginBottom:3}}>• {sk}</div>
                ))}</div>)}

              {/* Hintergrund-Zauber */}
              {((sheet.bgCantrips||[]).length > 0 || (sheet.bgSpells||[]).length > 0) && bgItem('zauber','✨','Hintergrund-Zauber','#9b59b6',
                [...(sheet.bgCantrips||[]), ...(sheet.bgSpells||[])].join(', '),
                <div>
                  {(sheet.bgCantrips||[]).length > 0 && (
                    <div style={{marginBottom:6}}>
                      <div style={{fontSize:10,color:MUTED,marginBottom:4,fontWeight:700}}>ZAUBERTRICKS (∞ Jederzeit)</div>
                      <div style={{display:'flex',flexWrap:'wrap',gap:4}}>
                        {(sheet.bgCantrips||[]).map((c,i)=>(
                          <span key={i} style={{fontSize:11,background:'#9b59b622',color:'#c39bd3',
                            padding:'3px 9px',borderRadius:6,border:'1px solid #9b59b644'}}>🔮 {c}</span>
                        ))}
                      </div>
                    </div>
                  )}
                  {(sheet.bgSpells||[]).length > 0 && (
                    <div>
                      <div style={{fontSize:10,color:MUTED,marginBottom:4,fontWeight:700}}>GRAD-1-ZAUBER (1×/tägl.)</div>
                      <div style={{display:'flex',flexWrap:'wrap',gap:4}}>
                        {(sheet.bgSpells||[]).map((s,i)=>(
                          <span key={i} style={{fontSize:11,background:'#5dade222',color:'#5dade2',
                            padding:'3px 9px',borderRadius:6,border:'1px solid #5dade244'}}>✨ {s}</span>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              )}

              {/* Hintergrund-Merkmal */}
              {bg.feature && bgItem('feature','📜','Hintergrund-Merkmal',MUTED,
                bg.feature.length > 60 ? bg.feature.slice(0,57)+'…' : bg.feature,
                bg.feature)}
            </>
          )}
        </div>
      )}

      {/* ── NOTIZEN ── */}
      <div style={{...S.card, marginBottom:8}}>
        <div style={{...S.row, justifyContent:'space-between', cursor:'pointer',
          marginBottom: notesOpen ? 10 : 0}}
          onClick={()=>setNotesOpen(v=>!v)}>
          <div style={{...S.label}}>📝 Notizen / Notes</div>
          <span style={{color:MUTED, fontSize:14, flexShrink:0}}>{notesOpen?'▲':'▼'}</span>
        </div>
        {notesOpen && (
          <>
            <div style={{...S.card, marginBottom:4}}>
              <div style={{...S.label, marginBottom:10}}>🧍 Aussehen / Appearance</div>
              <div style={{display:'grid', gridTemplateColumns:'1fr 1fr', gap:8}}>
                {appFields.map(f=>(
                  <div key={f.key}>
                    <div style={{fontSize:11, color:MUTED, marginBottom:3, fontWeight:600}}>{f.label}</div>
                    <input
                      style={{...S.inp, fontSize:13}}
                      placeholder={f.label + '…'}
                      value={sheet[f.key]||''}
                      onChange={e=>onUpdate({[f.key]:e.target.value})}/>
                  </div>
                ))}
              </div>
            </div>
            {textFields.map(([key,label])=>(
              <div key={key} style={{...S.card}}>
                <div style={{...S.label,marginBottom:6}}>{label}</div>
                <textarea style={{...S.inp, minHeight:80, resize:'vertical', fontFamily:'inherit'}}
                  value={sheet[key]||''}
                  onChange={e=>onUpdate({[key]:e.target.value})}
                  placeholder={`${label} hier eingeben...`}/>
              </div>
            ))}
            {customNotes.map(s=>(
              <div key={s.id} style={{...S.card}}>
                <div style={{display:'flex', alignItems:'center', gap:6, marginBottom:6}}>
                  <input
                    style={{...S.inp, flex:1, fontWeight:700, fontSize:13, padding:'4px 8px'}}
                    value={s.label}
                    onChange={e=>updateSection(s.id,'label',e.target.value)}
                    placeholder="Abschnittsname…"/>
                  <button onClick={()=>deleteSection(s.id)}
                    style={{background:'transparent', border:'1px solid #e74c3c44', borderRadius:6,
                      color:'#e74c3c', fontSize:12, padding:'4px 8px', cursor:'pointer', flexShrink:0}}>
                    🗑
                  </button>
                </div>
                <textarea style={{...S.inp, minHeight:80, resize:'vertical', fontFamily:'inherit'}}
                  value={s.content}
                  onChange={e=>updateSection(s.id,'content',e.target.value)}
                  placeholder={`${s.label} hier eingeben...`}/>
              </div>
            ))}
            <div style={{...S.card, border:`1px dashed ${accent}55`}}>
              <div style={{...S.label, marginBottom:8, color:accent}}>＋ Abschnitt hinzufügen</div>
              <div style={{display:'flex', gap:8}}>
                <input
                  style={{...S.inp, flex:1}}
                  placeholder="Name (z.B. Quests, Geheimnisse, NPCs…)"
                  value={newLabel}
                  onChange={e=>setNewLabel(e.target.value)}
                  onKeyDown={e=>e.key==='Enter' && addSection()}/>
                <button onClick={addSection}
                  style={{background: newLabel.trim() ? accent : '#1a1530',
                    color: newLabel.trim() ? '#111' : '#555',
                    border:`1px solid ${newLabel.trim() ? accent : '#333'}`,
                    borderRadius:8, padding:'6px 14px', fontWeight:700, fontSize:12,
                    cursor: newLabel.trim() ? 'pointer' : 'not-allowed', flexShrink:0}}>
                  ＋
                </button>
              </div>
            </div>
          </>
        )}
      </div>

      {/* ── HILFE ── */}
      <div style={{...S.card, marginBottom:8}}>
        <div style={{...S.row, justifyContent:'space-between', cursor:'pointer',
          marginBottom: helpOpen ? 10 : 0}}
          onClick={()=>setHelpOpen(v=>!v)}>
          <div style={{...S.label}}>❓ Hilfe / Regelwerk</div>
          <span style={{color:MUTED, fontSize:14, flexShrink:0}}>{helpOpen?'▲':'▼'}</span>
        </div>
        {helpOpen && (
          <>
            {helpSections.map(s=>(
              <div key={s.id} style={S.card}>
                <div style={{...S.row,justifyContent:'space-between',cursor:'pointer'}}
                  onClick={()=>setHelpSectionOpen(helpSectionOpen===s.id?null:s.id)}>
                  <span style={{fontWeight:600}}>{s.title}</span>
                  <span style={{color:MUTED}}>{helpSectionOpen===s.id?'▲':'▼'}</span>
                </div>
                {helpSectionOpen===s.id && (
                  <div style={{marginTop:8}}><DescText text={s.content}/></div>
                )}
              </div>
            ))}
            <div style={S.card}>
              <div style={{...S.row,justifyContent:'space-between',cursor:'pointer'}}
                onClick={()=>setHelpSectionOpen(helpSectionOpen==='kampfregel'?null:'kampfregel')}>
                <span style={{fontWeight:600}}>📖 Kampf-Regelwerk</span>
                <span style={{color:MUTED}}>{helpSectionOpen==='kampfregel'?'▲':'▼'}</span>
              </div>
              {helpSectionOpen==='kampfregel' && <div style={{marginTop:8}}>{kampfRegelwerk}</div>}
            </div>
          </>
        )}
      </div>
    </div>
  );
}

