const STORY_QUEST_KEY = 'dnd5e_story_quests';
const loadQuestLog  = () => { try { return JSON.parse(localStorage.getItem(STORY_QUEST_KEY)||'{}'); } catch { return {}; } };
const saveQuestLog  = q  => localStorage.setItem(STORY_QUEST_KEY, JSON.stringify(q));

